// 修复后的代码
function calculateScore(ores, multiplier, timeBonus) {
  let total = 0;

  // Fix 1: 修正数组遍历边界
  for (let i = 0; i < ores.length; i++) {
    if (ores[i] && ores[i].value !== undefined) {
      total += ores[i].value;
    }
  }

  total = total * multiplier + timeBonus;

  // Fix 2: 使用严格相等比较
  if (multiplier === 2) {
    console.log('Double score activated!');
  }

  return total;
}

function checkCollision(hook, ore) {
  // Fix 3: 添加钩子状态检查
  if (hook.state !== 'SHOOTING') {
    return false;
  }

  const dx = hook.x - ore.x;
  const dy = hook.y - ore.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  if (distance < hook.radius + ore.radius) {
    return true;
  }

  return false;
}

// 假设在游戏类中
class Game {
  constructor() {
    this.gameTime = 0;
    this.maxTime = 60;
  }

  updateGame(deltaTime) {
    // Fix 5: 处理 deltaTime 边界情况
    if (deltaTime <= 0 || deltaTime > 1000) {
      console.warn('Invalid deltaTime:', deltaTime);
      return;
    }

    // Fix 4: 使用实例变量
    this.gameTime += deltaTime;

    if (this.gameTime >= this.maxTime) {
      this.endGame();
    }

    this.player.score += Math.floor(deltaTime * 10);
  }
}
